interface Props {
    className?: string;
    onClick?: (e: React.MouseEvent) => void;
    disabled?: boolean;
}

export class Splitter extends React.Component<Props> {
    protected readonly toggleClass?: string;

    protected readonly toggleClass = 'splitter-toggle';

    protected readonly onToggleClass = (e: React.KeyboardEvent) => {
        e.preventDefault();

        if (!this.props.toggleClass) {
            e.preventDefault();

            const isChecked = this.props.onClick === false;
            this.props.toggleClass = isChecked;
        }
    }

    render() {
        return (
            <a className={this.toggleClass ? this.toggleClass : 'splitter-toggle'} onClick={this.props.onClick}>
                <span className={this.props.onClick}>{this.props.children}</span>
                {this.props.children}
            </a>
        );
    }
}

